<script setup lang="ts">
import {computed,ref,reactive,watch,onUnmounted,provide} from 'vue'
import {useAuthStore} from '../../../stores/auth'
import {listAdminTasks} from '../../../api/adminTasks'
import type {TaskQuery,TaskSummary,Page,TaskType} from '../../../api/adminTasks'
import {taskTypes,taskStates,taskStateLabel,taskTypeLabel,formatTaskTime,defaultDateRange} from './taskPresentation'
import TaskDetailPanel from './TaskDetailPanel.vue'
import TrainingTasksPanel from './TrainingTasksPanel.vue'
import {createAdminTaskAccess,taskAccessKey,taskIdentity} from './taskAccess'
const auth=useAuthStore()
const view=ref<'operations'|'training'>('operations')
const access=createAdminTaskAccess(()=>taskIdentity(auth.profile),()=>auth.refresh())
provide(taskAccessKey,access)
const canRead=computed(()=>!!auth.profile?.userId&&auth.profile.role==='ADMIN'&&!access.denied.value)
const draft=reactive({...defaultDateRange(),type:'',state:'',instrumentId:''})
const applied=ref<TaskQuery>({...defaultDateRange(),limit:20}),result=ref<Page<TaskSummary>|null>(null),busy=ref(false),error=ref(''),notice=ref(''),selected=ref<string|null>(null)
const cursors=ref<(string|undefined)[]>([undefined]),pageIndex=ref(0)
let epoch=0
function clear(){epoch++;result.value=null;selected.value=null;busy.value=false;error.value='';notice.value='';cursors.value=[undefined];pageIndex.value=0}
async function load(index=0,refresh=false,preserveSelection=false,replacePending=false){if(!canRead.value||(busy.value&&!replacePending))return;const sequence=++epoch,identity=taskIdentity(auth.profile);busy.value=true;error.value='';if(refresh){index=0;if(!preserveSelection)selected.value=null}const cursor=refresh?undefined:cursors.value[index];try{const value=await listAdminTasks(applied.value,cursor);if(sequence!==epoch||!canRead.value)return;result.value=value;pageIndex.value=index;cursors.value=refresh?[undefined]:cursors.value.slice(0,index+1);if(value.nextCursor)cursors.value[index+1]=value.nextCursor;notice.value=''}catch(e){if(access.reject(e,identity))return;if(sequence!==epoch)return;const failure=e as {status?:number;message?:string};if(failure.status===401||failure.status===403){result.value=null;selected.value=null}else if(result.value)notice.value='尚未刷新，以下保留上次查询结果';error.value=failure.message||'任务查询未完成'}finally{if(sequence===epoch)busy.value=false}}
function query(){if(busy.value)return;if(!draft.createdFrom||!draft.createdTo||draft.createdFrom>draft.createdTo){error.value='请选择有效的创建日期起止范围';return}const value:TaskQuery={createdFrom:draft.createdFrom,createdTo:draft.createdTo,limit:20,...(draft.type?{type:draft.type as TaskType}:{}),...(draft.state?{state:draft.state}:{}),...(draft.instrumentId?{instrumentId:draft.instrumentId.trim()}:{} )};clear();applied.value=value;void load()}
function reset(){Object.assign(draft,{...defaultDateRange(),type:'',state:'',instrumentId:''});query()}
watch([()=>auth.profile?.userId,()=>auth.profile?.role],()=>{access.reset();clear();if(canRead.value)void load()},{immediate:true,flush:'sync'})
watch(access.denied,value=>{if(value)clear()},{flush:'sync'})
onUnmounted(()=>{epoch++})
</script>
<template><main class="account-wrap task-workspace"><section class="account-card wide"><p class="eyebrow">管理员工作区</p><h1>任务管理</h1><p class="hint">查看行情更新、预测验证与股票比较更新，以及训练任务。取消任务需由管理员确认。</p><p v-if="access.denied.value" role="alert" class="task-error">管理员访问已失效，已清空任务数据。请刷新页面重新确认权限。</p><p v-else-if="!canRead" role="status">仅管理员可以查看任务。</p><template v-else>
<div class="task-actions" aria-label="任务类别">
  <button type="button" :aria-pressed="view==='operations'" @click="view='operations'">行情与验证任务</button>
  <button type="button" :aria-pressed="view==='training'" @click="view='training'">训练任务</button>
</div>
<TrainingTasksPanel v-if="view==='training'" :key="auth.profile?.userId"/>
<template v-else>
<form class="task-filters" @submit.prevent="query"><label>任务类型<select v-model="draft.type" data-test="task-type"><option value="">全部类型</option><option v-for="item in taskTypes" :key="item.value" :value="item.value">{{item.label}}</option></select></label><label>任务状态<select v-model="draft.state"><option value="">全部状态</option><option v-for="item in taskStates" :key="item.value" :value="item.value">{{item.label}}</option></select></label><label>股票代码<input v-model="draft.instrumentId" placeholder="如 SH600030" maxlength="16"/></label><label>创建日期起<input v-model="draft.createdFrom" type="date"/></label><label>创建日期止<input v-model="draft.createdTo" type="date"/></label><div class="task-actions"><button type="submit" data-test="task-query" :disabled="busy">{{busy?'查询中…':'查询'}}</button><button type="button" :disabled="busy" @click="reset">重置条件</button><button type="button" data-test="task-refresh" :disabled="busy" @click="load(0,true)">刷新列表</button></div></form>
<p class="small hint">按上海日期筛选；任务状态可能更新，刷新列表可重新查询。</p><p v-if="error" class="task-error" role="alert">{{error}}</p><p v-if="notice" class="task-stale" role="status">{{notice}}</p><p v-if="result" class="small" aria-live="polite">最近查询：{{formatTaskTime(result.queriedAt)}}（上海时间）</p>
<div v-if="result?.items.length" class="task-scroll" role="region" aria-label="任务列表，可横向滚动" tabindex="0"><table><caption class="sr-only">当前筛选下的三类任务</caption><thead><tr><th scope="col">任务</th><th scope="col">类型 / 股票</th><th scope="col">目标日期</th><th scope="col">状态</th><th scope="col">累计尝试</th><th scope="col">创建 / 更新</th><th scope="col">操作</th></tr></thead><tbody><tr v-for="task in result.items" :key="task.taskId"><td class="mono"><span aria-hidden="true">{{task.taskId.slice(0,8)}}…</span><span class="sr-only">{{task.taskId}}</span></td><td>{{taskTypeLabel(task.taskType)}}<br/>{{task.instrumentId}}</td><td>{{task.targetDate}}</td><td>{{taskStateLabel(task.state)}}</td><td>{{task.totalAttempts}}</td><td>{{formatTaskTime(task.createdAt)}}<br/>{{formatTaskTime(task.updatedAt)}}</td><td><button type="button" data-test="task-open" :aria-label="'查看任务 '+task.taskId+' 的详情'" @click="selected=task.taskId">查看详情</button></td></tr></tbody></table></div>
<p v-else-if="result&&!busy" role="status">当前条件下暂无任务。</p><div class="task-actions"><button type="button" data-test="task-prev" :disabled="busy||pageIndex===0" @click="load(pageIndex-1)">上一页</button><span>第 {{pageIndex+1}} 页</span><button type="button" data-test="task-next" :disabled="busy||!result?.hasMore" @click="load(pageIndex+1)">下一页</button></div>
<TaskDetailPanel v-if="selected" :key="selected" :task-id="selected" @missing="selected=null;notice='所选任务不存在，请重新查询列表'" @changed="load(0,true,true,true)"/>
</template></template></section></main></template>
<style>
.task-workspace .task-filters{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:16px;margin-bottom:16px}.task-workspace label{display:flex;flex-direction:column;gap:6px}.task-workspace input,.task-workspace select{font:inherit;min-height:44px;border:1px solid var(--border);border-radius:6px;padding:8px;width:100%;background:var(--surface);color:var(--ink)}.task-workspace button{font:inherit;min-height:44px;padding:8px 14px;border:1px solid var(--border);border-radius:6px;background:var(--surface);color:var(--accent);cursor:pointer}.task-workspace button:disabled{cursor:default;color:var(--muted);opacity:.65}.task-workspace :focus-visible{outline:3px solid var(--accent);outline-offset:2px}.task-actions{display:flex;align-items:center;flex-wrap:wrap;gap:10px;margin:16px 0}.task-filters .task-actions{grid-column:1/-1;margin:0}.task-scroll{max-width:100%;overflow-x:auto;margin:16px 0}.task-scroll table{border-collapse:collapse;min-width:850px;width:100%;font-size:14px;text-align:left}.task-scroll th{background:var(--canvas);font-weight:600}.task-scroll th,.task-scroll td{padding:12px;border-bottom:1px solid var(--border);vertical-align:top;white-space:nowrap}.task-error{color:#a21c23;background:#fff0f0;padding:12px;border-radius:6px}.task-stale{background:#fff6e7;color:#754500;padding:12px}.task-detail{margin-top:28px;padding-top:24px;border-top:1px solid var(--border)}.task-detail h2{margin-bottom:12px}.task-detail dl{display:grid;grid-template-columns:minmax(100px,160px) minmax(0,1fr);gap:10px 16px}.task-detail dt{color:var(--muted)}.task-detail dd{margin:0;overflow-wrap:anywhere}.mono{font-family:ui-monospace,monospace}.task-workspace .sr-only{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:700px){.task-workspace .task-detail dl{grid-template-columns:1fr;gap:4px}.task-workspace .task-detail dd{margin-bottom:12px}.task-workspace .task-filters{grid-template-columns:1fr}}
</style>
